with cleaned as (select *, case when device_code in ('DV-04', 'DV-03') then 'Core' else 'Other' end as device_code_group from device_readings where humidity >= 34) select date_trunc('day', reading_ts) as activity_day, count(*) filter (where device_code = 'DV-02') as dv_02_rows, percentile_approx(pressure, array(0.25, 0.5, 0.75)) as pressure_quartiles, count_if(device_code = 'DV-03') as dv_03_events, stddev_samp(pressure) as pressure_stddev, approx_percentile(humidity, 0.95) as humidity_p95, round(sum(status_bits) / nullif(count(case when device_code = 'DV-03' then 1 end), 0), 2) as status_bits_per_dv_03 from cleaned group by activity_day having humidity_p95 >= 0;
